/**
 * /roster-construction — Roster Construction V1, end to end in the browser
 * (owner directive 2026-10-30; flag `roster_construction`, default OFF).
 *
 * GET /api/roster-construction is answered by page.route — the flag ships OFF,
 * so the live stack would only ever show "not available".  The team payload is
 * the backend's golden fixtures
 * frontend/__tests__/fixtures/roster-construction/golden-best-ball-v1.json and
 * golden-managed-v1.json (generated by the real module); the mock re-stamps
 * only league and team so the page's stale-answer guard accepts them.  What this pins is the browser
 * half: the page exists only behind the gate, the team list comes from the
 * overview and no team is guessed, picking a team sends that team, production
 * and dynasty value render as separate tables with their own denominators,
 * the three start concepts are labelled apart, diagnoses show evidence and an
 * explicit NO ACTION, no sideways scroll at 390 px, and axe is clean on the
 * populated state.  Runs on every project (desktop and phone, including WebKit
 * mobile-390).
 *
 * This is NOT the Phase 5 production acceptance (a real league against real
 * history): that needs the flag on against production data, an owner action.
 *
 * Auth: test-only session fixture (skips when E2E_TEST_SECRET is unset).
 */
const fs = require("fs");
const path = require("path");
const { test, expect } = require("../helpers/auth-fixture");
const { pageUrl, awaitStreamSettled, isNavigationAbortedFetch } = require("../helpers/journey");
const AxeBuilder = require("@axe-core/playwright").default;

test.use({ serviceWorkers: "block" });

const TAGS = ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa"];
const FIXTURE_DIR = path.resolve(
  __dirname,
  "../../../frontend/__tests__/fixtures/roster-construction",
);
const load = (name) => JSON.parse(fs.readFileSync(path.join(FIXTURE_DIR, `${name}.json`), "utf-8"));
const BEST_BALL = load("golden-best-ball-v1");
const MANAGED = load("golden-managed-v1");

function overviewOf(fx) {
  return {
    schemaVersion: fx.schemaVersion,
    leagueKey: fx.leagueKey,
    season: fx.season,
    rules: fx.rules,
    teams: fx.teams,
  };
}

function json(route, status, body) {
  return route.fulfill({
    status,
    contentType: "application/json",
    headers: { "Cache-Control": "no-store" },
    body: JSON.stringify(body),
  });
}

/** Mock the endpoint; returns the team requests (those that carried a rosterId). */
async function mockEndpoint(page, { off = false, fixture = BEST_BALL } = {}) {
  const teamCalls = [];
  await page.route(
    (url) => url.pathname === "/api/roster-construction",
    (route) => {
      if (off) return json(route, 503, { error: "feature_disabled", flag: "roster_construction" });
      const url = new URL(route.request().url());
      const leagueKey = url.searchParams.get("leagueKey") || fixture.leagueKey;
      const rosterId = url.searchParams.get("rosterId");
      if (!rosterId) return json(route, 200, { ...overviewOf(fixture), leagueKey });
      teamCalls.push({ leagueKey, rosterId });
      const label = fixture.teams.find((t) => String(t.rosterId) === rosterId)?.label;
      return json(route, 200, {
        ...fixture,
        leagueKey,
        team: {
          ...fixture.team,
          rosterId: Number(rosterId),
          label: label || fixture.team.label,
        },
      });
    },
  );
  return teamCalls;
}

/**
 * Panels transition their background from the terminal surface to the editorial
 * cream on first paint (slower on WebKit); axe reads the mid-transition colour.
 * Scan only once every panel has settled on the editorial --surface-1.
 */
async function settleSurfaces(page) {
  await expect
    .poll(
      () =>
        page.evaluate(() =>
          [...document.querySelectorAll(".ds-panel")].every(
            (e) => getComputedStyle(e).backgroundColor === "rgb(250, 246, 236)",
          ),
        ),
      { timeout: 15_000 },
    )
    .toBe(true);
}

async function noPageOverflow(page) {
  const sizes = await page.evaluate(() => ({
    document: document.documentElement.scrollWidth,
    viewport: document.documentElement.clientWidth,
  }));
  expect(sizes.document, "the page must not scroll sideways").toBeLessThanOrEqual(sizes.viewport + 1);
}

async function openPage(page) {
  await page.goto(pageUrl("/roster-construction"));
  await awaitStreamSettled(page);
  const root = page.getByTestId("roster-construction");
  await expect(root).toBeVisible({ timeout: 60_000 });
  // Headless WebKit does not advance CSS transitions without a frame, so a
  // panel's background can sit mid-transition at the terminal colour and axe
  // reads that.  Transitions are not under test here.
  await page.addStyleTag({ content: "*,*::before,*::after{transition:none!important}" });
  return root;
}

test("roster construction: gate, real team, separate measures, starts, diagnoses, 390 px, axe clean", async ({
  authedPage: page,
}, testInfo) => {
  const errors = [];
  page.on("pageerror", (e) => {
    if (!isNavigationAbortedFetch(e, page)) errors.push(e.message);
  });
  const calls = await mockEndpoint(page);
  const root = await openPage(page);

  // No team is guessed: the selector is empty and nothing team-scoped was requested.
  const team = root.getByLabel("Team");
  await expect(team).toHaveValue("");
  await expect(root.getByRole("heading", { name: "Pick a team" })).toBeVisible();
  expect(calls).toHaveLength(0);

  // Pick a real team from the backend's overview.
  await team.selectOption("1");
  const panel = page.getByTestId("roster-construction-panel");
  await expect(panel).toBeVisible({ timeout: 30_000 });
  await expect(page.getByTestId("rc-summary")).toContainText("Team 1");
  expect(calls[0]).toMatchObject({ rosterId: "1" });
  await expect(panel.getByText("Two independent measures")).toBeVisible();

  // Production and dynasty value are separate tables, each rank with its own denominator.
  const production = panel.getByRole("table", { name: /optimal starter points by position/ });
  const value = panel.getByRole("table", { name: /Dynasty value held at each position/ });
  await expect(production).toBeVisible();
  await expect(value).toBeVisible();
  await expect(production.getByRole("row").filter({ hasText: "6 of 6" }).first()).toBeVisible();
  await expect(value.getByRole("row").filter({ hasText: "1 of 6" }).first()).toBeVisible();

  // The three start concepts, with denominators and the hypothetical assumption.
  const players = panel.getByRole("table", { name: /Per-player starts/ });
  await players.getByRole("row").filter({ hasText: "t1-te9" }).click();
  const detail = page.getByTestId("rc-player-detail");
  await expect(detail).toBeVisible();
  await expect(detail).toContainText("Actual optimized starts while owned");
  await expect(detail).toContainText("Hypothetical optimal starts");
  await expect(detail).toContainText("League-relative startability");
  await expect(detail).toContainText("0 of 8");
  await expect(detail).toContainText("Injured");
  await expect(detail).toContainText("ex post");

  // Diagnoses: evidence and an explicit NO ACTION beside a REVIEW.
  const d1 = page
    .locator('[data-testid="rc-diagnosis"][data-rule="RC-D1"]')
    .filter({ hasText: "No action" });
  await expect(d1).toContainText("No action");
  await expect(d1).toContainText("1 of 6");
  await expect(page.getByTestId("rc-overall")).toContainText("Overall: Review");

  await noPageOverflow(page);
  // The sticky top bar (WebKit phone) overlaps whatever has scrolled beneath it,
  // and axe reads the bar's background for those controls; scan from the top.
  await page.evaluate(() => window.scrollTo(0, 0));
  await settleSurfaces(page);
  const axe = await new AxeBuilder({ page })
    .withTags(TAGS)
    .include('[data-testid="roster-construction"]')
    .analyze();
  await testInfo.attach("roster-construction-axe", {
    body: JSON.stringify(axe.violations, null, 2),
    contentType: "application/json",
  });
  expect(axe.violations).toEqual([]);
  await panel.screenshot({ path: testInfo.outputPath("roster-construction.png") });

  // Switching team re-requests that team (stale answers are discarded).
  await team.selectOption("3");
  await expect(page.getByTestId("rc-summary")).toContainText("Team 3", { timeout: 30_000 });
  expect(calls.at(-1).rosterId).toBe("3");
  await noPageOverflow(page);

  expect(errors, "no uncaught page errors").toEqual([]);
});

test("roster construction: a manual-lineup league is labelled hypothetical optimal, 390 px, axe clean", async ({
  authedPage: page,
}, testInfo) => {
  const calls = await mockEndpoint(page, { fixture: MANAGED });
  const root = await openPage(page);
  await root.getByLabel("Team").selectOption("2");
  const panel = page.getByTestId("roster-construction-panel");
  await expect(panel.getByText("Hypothetical optimal lineups", { exact: true })).toBeVisible({ timeout: 30_000 });
  expect(calls[0]).toMatchObject({ rosterId: "2" });
  await expect(page.getByTestId("rc-summary")).toContainText("Hypothetical optimal");
  await expect(page.getByTestId("rc-summary")).toContainText("8 weeks with an observed submitted lineup");
  await expect(
    panel.getByRole("table", { name: /hypothetical optimal starter points by position/ }),
  ).toBeVisible();
  // A lineup marginal that best ball alone can compute is stated unknown.
  await panel
    .getByRole("table", { name: /Per-player starts/ })
    .getByRole("row")
    .filter({ hasText: "t2-db1" })
    .click();
  await expect(page.getByTestId("rc-player-detail")).toContainText("best-ball leagues");
  await noPageOverflow(page);
  // The sticky top bar (WebKit phone) overlaps whatever has scrolled beneath it,
  // and axe reads the bar's background for those controls; scan from the top.
  await page.evaluate(() => window.scrollTo(0, 0));
  await settleSurfaces(page);
  const axe = await new AxeBuilder({ page })
    .withTags(TAGS)
    .include('[data-testid="roster-construction"]')
    .analyze();
  await testInfo.attach("roster-construction-managed-axe", {
    body: JSON.stringify(axe.violations, null, 2),
    contentType: "application/json",
  });
  expect(axe.violations).toEqual([]);
});

test("roster construction: no page while its flag is off", async ({ authedPage: page }) => {
  await mockEndpoint(page, { off: true });
  const probed = page.waitForResponse(
    (r) => new URL(r.url()).pathname === "/api/roster-construction" && r.status() === 503,
  );
  await page.goto(pageUrl("/roster-construction"));
  await probed;
  await expect(page.getByTestId("roster-construction-unavailable")).toBeVisible({ timeout: 30_000 });
  await expect(page.getByTestId("roster-construction")).toHaveCount(0);
  await expect(page.locator("#rc-team")).toHaveCount(0);
});
